def PHOTO(f,alt,cap):return f'<figure><img src="images/microprocessors/{f}" alt="{alt}" loading="lazy"><figcaption>{cap}</figcaption></figure>'
def LIMG(f,alt,cap):return IMG(f'{SRC}/{f}',alt,cap)
def H(t):return f'<h2>{t}</h2>'
def Pp(t):return f'<p>{t}</p>'
def UL(items,tag='ul'):return f'<{tag}>'+''.join(f'<li>{i}</li>' for i in items)+f'</{tag}>'
def chip(x,y,w,h,pins=6,c='bx'):
    o=R(x,y,w,h,c,4);s=w/(pins+1)
    for i in range(1,pins+1):o+=L(x+i*s,y-6,x+i*s,y)+L(x+i*s,y+h,x+i*s,y+h+6)
    return o
def sq(x0,y,n,per,hgt,c='ln'):  # square wave, n periods
    d=f'M{x0} {y}'
    for i in range(n):
        a=x0+i*per;d+=f' L{a} {y-hgt} L{a+per/2} {y-hgt} L{a+per/2} {y} L{a+per} {y}'
    return f'<path d="{d}" class="{c}" fill="none"/>'

