    o+=A(130,80,182,80,'lna','hda')+T(156,70,'1958–59','t-s ac t-b')
    o+=R(196,26,128,108,'bxa',6)+T(260,46,'бір кристалл','t-s t-b')
    for x,y in [(220,70),(260,70),(300,70),(220,108),(260,108),(300,108)]:o+=R(x-9,y-8,18,16,'bx',2)
    o+=L(229,70,251,70)+L(269,70,291,70)+L(220,78,220,100)+L(300,78,300,100)+L(269,108,291,108)
    o+=T(260,150,'элементтер мен «сымдар»','t-s')+T(260,164,'бір кристалда жасалады','t-s')
