def bits():
    rows=[('1971','4 бит','Intel 4004','16 мән',4),('1972','8 бит','Intel 8008','256 мән',8),('1978','16 бит','Intel 8086','65 536 мән',16),('1985','32 бит','Intel 80386','≈4,3 млрд',32),('2003','64 бит','x86-64 (AMD)','≈1,8·10¹⁹',64)]
    o=''
    for i,(y,b,n,v,w) in enumerate(rows):
        yy=14+i*38
        o+=TL(4,yy+14,y,'t-s t-b')+R(42,yy,w*2.4,22,'bxa' if i==4 else 'soft',3)+TL(46,yy+15,b,'t-s t-b')+TL(204,yy+10,n,'t-s')+TL(204,yy+24,v,'t-s mu')
    return o
