def moore():
    import math
    x0,y0,w,h=46,180,280,160   # years 1970..2005, log10 3..8
    X=lambda yr:x0+(yr-1970)/35*w
    Y=lambda n:y0-(math.log10(n)-3)/5*h
    o=L(x0,y0,x0+w,y0)+L(x0,y0,x0,y0-h)
    for e in range(3,9):o+=TR(x0-4,Y(10**e)+4,f'10{"³⁴⁵⁶⁷⁸"[e-3]}','t-s mu')+L(x0-3,Y(10**e),x0,Y(10**e))
    for yr in (1970,1980,1990,2000):o+=T(X(yr),y0+14,str(yr),'t-s mu')
    o+=f'<line x1="{X(1971):.1f}" y1="{Y(2300):.1f}" x2="{X(2003):.1f}" y2="{Y(2300*2**16):.1f}" class="ln dash"/>'
    pts=[(1971,2300,'4004'),(1978,29000,'8086'),(1985,275000,'80386'),(2000,42e6,'Pentium 4')]
    for yr,n,lab in pts:o+=f'<circle cx="{X(yr):.1f}" cy="{Y(n):.1f}" r="4" class="ac"/>'+TL(X(yr)+7,Y(n)+(-6 if lab=='4004' else 14),lab,'t-s t-b')
    o+=TL(x0+6,14,'транзистор саны (логарифмдік шкала)','t-s mu')+TL(196,150,'пунктир: әр 2 жыл ×2','t-s ac')
    return o
f_moore=F(S(340,200,moore(),'Мур заңы'),'Транзистор саны: нақты процессорлар (нүкте) және «әр 2 жылда екі есе» сызығы')

def ai():
    o=TL(4,14,'CPU: бірнеше күшті ядро','t-s t-b')
    for i in range(4):o+=B(4+i*42,22,38,36,'ядро','bxa','t-s')
    o+=TL(176,14,'GPU: мыңдаған ұсақ ядро','t-s t-b')
    for r in range(5):
        for c in range(16):o+=R(176+c*9.5,22+r*7.6,7,5.4,'soft',1)
    o+=TL(4,86,'NPU: нейрон желісінің негізгі амалына','t-s t-b')+TL(4,100,'арналған блок (матрица × матрица)','t-s t-b')
    for r in range(3):
        for c in range(3):o+=R(40+c*18,112+r*18,14,14,'bx',2)
    o+=T(106,140,'×','t-b')
    for r in range(3):
        for c in range(3):o+=R(118+c*18,112+r*18,14,14,'bx',2)
    o+=T(184,140,'=','t-b')
    for r in range(3):
        for c in range(3):o+=R(196+c*18,112+r*18,14,14,'soft',2)
    o+=T(170,186,'бір операцияда көп көбейту мен қосу, аз энергиямен','t-s mu')
    return o
