def steps500():
    st=['1. датчик\n480 °C','2. енгізу\nқұрылғысы','3. деректер\nшинасы','4. регистр','5. АЛҚ\n480 &lt; 500','6. БҚ\n«қыздыр!»','7. шығару\nқұрылғысы','қыздырғыш\nқосылды']
    o=''
    for i,t in enumerate(st):
        r,c_=divmod(i,4);c_=c_ if r==0 else 3-c_
        x=4+c_*84;y=10+r*78;o+=B(x,y,76,46,t,'bxa' if i in(4,5) else ('soft' if i==7 else 'bx'),'t-s',lh=15)
        if i<7:
            if i==3:o+=A(x+38,y+46,x+38,y+78)
            elif r==0:o+=A(x+76,y+23,x+84,y+23)
            else:o+=A(x,y+23,x-8,y+23)
    return o+T(170,160,'температура өлшенеді де, цикл қайталанады','t-s mu')
f_500=F(S(340,168,steps500(),'500 °C мысалы'),'Лекциядағы мысал: пешті 500 °C-та ұстау кезіндегі ақпарат жолы (7 қадам)')

