def pack(lid,order,title,parts,cards,fn):
    d={"format":"besminut-pack","version":1,"course":course,"lectures":[{"id":lid,"order":order,"title":title,"source":"material","parts":parts,"cards":[{"f":f,"b":b} for f,b in cards]}]}
    json.dump(d,open(f'{OUT}/{fn}','w',encoding='utf-8'),ensure_ascii=False)
    print(fn,len(parts),'parts',len(cards),'cards',os.path.getsize(f'{OUT}/{fn}')//1024,'KB')
pack('microprocessors-01-history',1,'1-сабақ. Микропроцессорлардың даму тарихы. Негізгі ұғымдар',L1,cards1,'01-history.json')
pack('microprocessors-02-structure',2,'2-сабақ. Микропроцессорлық жүйенің құрылымы',L2,cards2,'02-structure.json')
json.dump([{"kk":a,"ru":b,"en":c,"abbr":d} for a,b,c,d in glossary],open(f'{OUT}/glossary.json','w',encoding='utf-8'),ensure_ascii=False,indent=1)
